    text = "\n".join(p.text for p in checked.paragraphs)
    print({"output": str(output), "sections": len(SECTIONS), "paragraphs": len(checked.paragraphs),
           "tables": len(checked.tables), "body_words": len(text.split()), "bytes": output.stat().st_size})


